'use client'

import Link from 'next/link'

import { getTrackArray, setupSongGallery } from '@/app/actions/song_modify'
import { useEffect, useState } from 'react'

export default function Home() {
  const [songArray, setSongs] = useState(null)
  const [curPage, setPage]  = useState(0)
  const [loading, setLoading] = useState(true)

  const perPage = 5; let numOfPages
  useEffect(() => {
    async function fetchArray() {
      try {
        const dataArray = await getTrackArray()

        setSongs(await setupSongGallery(dataArray, [curPage * perPage, curPage * perPage + perPage]))
        numOfPages = Math.floor(dataArray.length / perPage)
      } catch (err) {
        console.error(err)
      } finally {
        setLoading(false)
      }
    }

    fetchArray()
  }, [])  
  return (
  <>
    <main>
      <p>
        <button onClick={() => setPage((curPage) => curPage - 1) }>poprzednia strona</button>
        {String(curPage + 1)}
        <button onClick={() => setPage((curPage) => curPage + 1) }>nastepna strona</button>
      </p>

      {loading && <div>wczytywanie piosenek</div>}
      {!loading && songArray.map(song => (
          <Link key={song.id} href={"./display?id=" + song.id}>
            <h2>{song.title}</h2>
            <p>{song.artist}</p>
          </Link>
      ))}
    </main>
  </>
  )
}
